/* ─── 教育学 ────────────────────────────────────────────────── */
window.QB_TE_EDU = [
  {c:'教师',q:'教育的本质属性是？',
   o:['政治现象','经济现象','有目的地培养人的社会活动','自然现象'],
   a:2,e:'教育的本质属性是"有目的地培养人的社会活动"，这是教育区别于其他社会现象的根本特征，也是教育学研究的核心命题。'},
  {c:'教师',q:'以下哪位学者被称为"现代教育学之父"？',
   o:['赫尔巴特','卢梭','杜威','夸美纽斯'],
   a:0,e:'赫尔巴特（德国）著有《普通教育学》（1806年），第一次将心理学作为教育学的理论基础，建立了科学形态的教育学体系，被称为"现代教育学之父"或"科学教育学之父"。'},
  {c:'课程',q:'影响人身心发展的因素中，起主导作用的是？',
   o:['遗传因素','环境因素','学校教育','社会实践活动'],
   a:2,e:'在遗传、环境、学校教育、个体主观能动性四大因素中，学校教育对人的身心发展起主导作用，因为学校教育目的明确、内容系统、方法专业，具有最强的计划性和组织性。'}
];

