  o: ['1957《关于正确处理人民内部矛盾的问题》', '1985年《中共中央关于教育体制改革的决定》', '1999年《中共中央国务院关于深化教育改革，全面推进素质教育的决定》', '2010年《国家中长期教育改革和发展规划纲要（2010-2020年）》'],
