    c:'课程',
    q:'下列有关课程目标的表述正确的是（ ）。',
    o:['课程目标是课程组织的预期结果','课程目标是课程本身要实现的具体目标和意图','高年级课程目标是低年级目标的延续和深化','教育目的和学校的培养目标是制定课程目标的直接依据'],
    a:[1,2,3],
    e:'课程目标是课程本身要实现的具体目标和意图，高年级目标是低年级目标的延续和深化，教育目的和学校培养目标是制定课程目标的直接依据（BCD正确）。A选项错误，课程组织是实现课程目标的手段，课程目标是课程本身的预期结果，而非课程组织的预期结果。'
