    a:[0,1,3],
    e:'教师进行教学的直接依据是课程标准，因此不属于直接依据的是课程计划、课程目标和教科书（ABD正确）。课程计划是学校整体教学的宏观规划；课程目标是教学的方向性指引；教科书是课程标准的载体与教学材料，三者均不是教学的直接依据。'
