/* 普通心理学 - 第1模块：心理学概述*/
window.QB_TE_GPSY_B1=[
{
    c:'心理学概述',
    q:'在发展心理学里，常用的研究方法有（ ）。',
    o:['横断设计','纵向设计','双生子设计','聚合交叉设计'],
    a:[0,1,2,3],
    e:'发展心理学的常用研究方法包括横断设计、纵向设计、双生子设计、聚合交叉设计。横断设计是同一时间点对不同年龄组被试测试，是发展心理学最基础常用的研究设计；纵向设计是对同一组被试长期追踪，观察个体发展变化；双生子设计用于探究遗传与环境对心理发展的影响；聚合交叉设计结合了横断与纵向设计的优势，是当前发展心理学研究的主流方法之一。'
},
{
    c:'心理学概述',
    q:'机能主义心理学是19世纪末、20世纪初出现在美国的一个心理流派，是美国第一个本土心理学流派。下列关于机能主义心理学的表述错误的有（ ）。',
    o:['重视实验的研究方法，反对内省的实验方法','卡尔是机能主义心理学的代表人物之一','强调意识的结构和作用','把意识看成是若干有限元素的集合'],
    a:[0,2,3],
    e:'机能主义心理学并不反对内省法，仅反对构造主义纯训练式的描述性内省，其研究方法开放多元，因此A选项表述错误；卡尔是机能主义心理学后期的核心代表人物，B选项表述正确；机能主义心理学核心研究意识的功能，而非意识的结构，研究意识结构是构造主义的主张，因此C选项表述错误；把意识看成若干有限元素的集合是构造主义心理学的观点，机能主义认为意识是连续的意识流，因此D选项表述错误。本题要求选择表述错误的选项，答案为ACD。'
},
{
    c:'心理学概述',
    q:'下列属于认知心理学代表人物的有（ ）。',
    o:['维果斯基','罗杰斯','马斯洛','加德纳'],
    a:[0,3],
    e:'认知心理学核心研究人的认知过程与认知发展，维果斯基的认知发展理论、加德纳的多元智能理论均属于认知心理学的核心内容，二者是认知心理学的代表人物；罗杰斯、马斯洛是人本主义心理学的代表人物，不属于认知心理学流派。'
},
{
    c:'心理学概述',
    q:'荣格心理学将人格结构分为以下哪几个层次？（ ）',
    o:['意识','超我意识','个人潜意识','本我意识','集体潜意识'],
    a:[0,2,4],
    e:'荣格心理学将人格结构分为三个层次：意识、个人潜意识、集体潜意识。意识是人格的表层结构，是个体可直接感知的心理内容；个人潜意识是个体曾经意识到但被压抑、遗忘的内容；集体潜意识是人类祖先世代传递的共同经验，是荣格人格理论的核心。超我意识、本我意识是弗洛伊德人格结构理论的内容，不属于荣格的人格结构划分。'
},
{
    c:'心理学概述',
    q:'下列符合人本主义心理学流派教育观的有（ ）。',
    o:['认为教学应以学生为中心','认为心理学研究行为的任务在于查明刺激与反应之间的规律性关系','强调教育者要创设有利于学习的环境，尽可能强化学生的行为','强调学生的尊严、价值、创造力和自我实现'],
    a:[0,3],
    e:'人本主义心理学教育观的核心是以学生为中心，尊重学生的人格与价值，强调学生的自我实现，因此A、D选项符合人本主义教育观。B选项研究刺激与反应的规律、C选项通过强化控制学生行为，均属于行为主义心理学的主张，与人本主义教育观相悖。'
},
];

