o: ['两次测量之间的时距相距3个月以上，练习效应可忽略不计','被试者的应试动机很重要','一般的平均练习效应，约在1/5个标准差以下，且仅限于第一次及第二次重测','一般的平均练习效应，约在1/3个标准差以下，且仅限于第一次及第二次重测'],
a: [0,1,2],
