        o:['强调身心参与，注重手脑并用是劳动教育的核心理念','在大中小学设立劳动教育必修课程，中小学劳动教育课平均每周不少于2课时','中小学要建立以学校为主导、家庭为基础、社区为依托的协同实施机制，形成共育合力','发挥主体作用，激发创新创造是开展劳动教育的基本理念'],
