{c:'教育',q:'下列表述不符合《中华人民共和国义务教育法》规定的是（ ）。',o:['义务教育阶段不收取任何费用','凡年满六周岁的儿童必须接受义务教育','国家机关工作人员可以参与或变相参与教科书的编写','义务教育经费的保障具体办法由国务院规定'],a:[0,1,2],e:'本题选不符合规定的选项。A错误，义务教育阶段免收学费、杂费，并非不收取任何费用；B错误，凡年满六周岁的儿童，其父母或其他法定监护人应当送其入学接受并完成义务教育，条件不具备的地区的儿童，可以推迟到七周岁，并非绝对“必须”；C错误，国家机关工作人员和教科书审查人员，不得参与或者变相参与教科书的编写工作；D符合法律规定。'}
