/* 综合模拟卷 */
window.QB_TE_EXAM1=[
  {c:'教育',q:'根据个体身心发展的顺序性，教学中应？',o:['跳跃式教学','循序渐进，由浅入深，不能超越发展阶段','随意安排顺序','先难后易'],a:1,e:'顺序性：发展有固定顺序，教学必须循序渐进，不能超越或颠倒发展阶段（"揠苗助长"是违背顺序性的错误做法）。'},
  {c:'心理',q:'最近发展区是指学生？',o:['当前实际发展水平','实际发展水平与潜在发展水平之间的差距（在成人帮助下能达到的水平与现有水平的差距）','未来发展方向','最高发展水平'],a:1,e:'最近发展区（维果斯基）：学生独立解决问题的实际水平与在成人（教师/同伴）帮助下能达到的水平之间的差距，教学应在此区间内进行，"教学走在发展的前面"。'},
  {c:'教育',q:'下列属于教师职业道德基本规范的是？',o:['爱岗敬业、爱生如子、知识渊博','爱国守法、爱岗敬业、关爱学生、教书育人、为人师表、终身学习','只需知识丰富','只需态度好'],a:1,e:'教师职业道德六条规范（教育部《中小学教师职业道德规范》）：爱国守法、爱岗敬业、关爱学生、教书育人、为人师表、终身学习。这六条是教师执教的基本准则。'},
  {c:'心理',q:'根据艾宾浩斯遗忘曲线，最佳复习时机是？',o:['一个月后','学习后立即复习并在24小时内进行第一次复习（遗忘最快时）','一周后','考试前夕'],a:1,e:'艾宾浩斯遗忘曲线：遗忘先快后慢，学后24小时遗忘量最大。因此复习应：学后立即复习，24小时内进行第一次系统复习，之后按间隔递增安排复习（间隔重复法）。'},
  {c:'教育',q:'斯金纳"程序教学"的核心原则是？',o:['大班讲授','小步子呈现，即时强化，学生主动反应，自定步调，低错误率','竞争机制','惩罚错误'],a:1,e:'斯金纳程序教学原则：①小步骤呈现（由简到繁，每次学习量小）②积极反应（学生主动参与）③即时反馈（立即告知对错）④自定步调（按自己速度学习）⑤低错误率（设计难度递进）。'},
];
window.QB_TE_EXAM2=[
  {c:'教育',q:'三维目标"过程与方法"是指？',o:['只是教学过程的时间安排','学生在学习过程中采用的学习方式和方法，以及体验探究的过程','考试方法','只是教学方法'],a:1,e:'"过程与方法"维度：不只是让学生获得结论，更要让学生经历探究、思考、实践的过程，掌握科学的学习方法，体验知识形成的过程，培养学习能力。'},
  {c:'心理',q:'班杜拉自我效能感的含义是？',o:['对自己智力的评价','个体对自己能否完成某一任务的信念和判断，影响行为的选择和坚持性','学习成绩的评价','对他人能力的评价'],a:1,e:'自我效能感（班杜拉）：个体对自己完成特定任务能力的信念。高自我效能感→更有信心→更努力坚持→更可能成功。影响因素：成功经验（最重要）、替代经验（观察榜样）、言语劝说、生理状态。'},
  {c:'教育',q:'新课程改革的核心理念是？',o:['以知识为本（强调知识传授）','以学生发展为本（促进学生全面发展，关注过程和情感）','以考试为本','以教材为本'],a:1,e:'新课改核心理念："以学生发展为本"，从"关注知识"转向"关注学生"，从"传授知识"转向"培养能力和素养"，强调三维目标，倡导自主合作探究的学习方式。'},
  {c:'心理',q:'马斯洛需要层次理论从低到高依次是？',o:['安全→生理→归属→尊重→自我实现','生理→安全→归属和爱→尊重→自我实现','自我实现→尊重→归属→安全→生理','尊重→安全→生理→归属→自我实现'],a:1,e:'马斯洛需要层次（从低到高）：生理（吃喝睡）→安全（稳定安全）→归属和爱（友情爱情）→尊重（自尊和他人尊重）→自我实现（潜能发挥，最高层）。只有低级需要基本满足，才会出现高级需要。'},
  {c:'教育',q:'影响课程计划实施的关键因素是？',o:['课程计划本身完美无缺','教师的专业素养和教学能力（教师是课程实施的核心主体）','只有教材质量','只有学生配合'],a:1,e:'课程实施的关键在于教师：教师的教育理念、专业能力、创造力和投入程度，直接决定课程计划能否有效转化为实际的教育实践，教师是课程改革成败的关键。'},
];
